import Foundation

/// A generated study artifact for a collection (Create tab / artifact studio).
/// Backend: api/app/routers/artifacts.py — generated by an open-source
/// Fireworks model grounded in the collection's own sources.
struct Artifact: Codable, Identifiable, Equatable {
    let id: UUID
    let collectionId: UUID
    let kind: String          // "quiz" | "paper"
    let title: String
    let status: String        // "ready" | "failed"
    let content: ArtifactContent?
    let model: String?
    let createdAt: String

    static func == (lhs: Artifact, rhs: Artifact) -> Bool { lhs.id == rhs.id }
}

/// Free-form artifact payload. Fields are all-optional because the shape
/// depends on `kind`:
///   quiz  → questions
///   paper → markdown + outline
struct ArtifactContent: Codable, Equatable {
    var questions: [QuizQuestion]?
    var markdown: String?
    var outline: [String]?
}

struct QuizQuestion: Codable, Equatable, Identifiable {
    var id: String { q }
    let q: String
    let options: [String]
    let answer: Int           // 0-based index of the correct option
    let why: String
}

struct ArtifactCreateRequest: Encodable {
    let kind: String
}
